-- Function: public.ensure_tenant_roles
-- Backup generated on 2026-10-25 20:32:53

CREATE OR REPLACE FUNCTION public.ensure_tenant_roles(p_tenant uuid)  RETURNS void  LANGUAGE plpgsql AS $function$ BEGIN     INSERT INTO roles (tenant_id, name, description, scope_type)     SELECT p_tenant, v.n, v.n, 'Organization'     FROM (VALUES ('OrganizationOwner'), ('OrganizationAdmin'), ('BranchAdmin'), ('DaycareTeacher'), ('ClassroomTeacher')) AS v(n)     WHERE NOT EXISTS (SELECT 1 FROM roles r WHERE r.tenant_id = p_tenant AND r.name = v.n);      UPDATE roles SET scope_type = 'Organization'     WHERE tenant_id = p_tenant AND name IN ('OrganizationOwner', 'OrganizationAdmin', 'BranchAdmin', 'DaycareTeacher', 'ClassroomTeacher');      DELETE FROM role_permissions rp USING roles r     WHERE rp.role_id = r.id AND r.tenant_id = p_tenant       AND r.name IN ('OrganizationOwner', 'OrganizationAdmin', 'BranchAdmin', 'DaycareTeacher', 'ClassroomTeacher');      INSERT INTO role_permissions (role_id, permission_id)     SELECT r.id, p.id     FROM enjoy_role_template() t     JOIN roles r ON r.tenant_id = p_tenant AND r.name = t.role_name     JOIN permissions p ON p.name = t.permission_name     ON CONFLICT DO NOTHING; END $function$ ;
